let creatorStage='writer',creatorTaskScope='',creatorTaskQuery='',objectType='character',objectId=null,objectStatus='',objectScope='',thumbnailRound=0;
const thumbnailCache=new Map();
function currentObject(){return objectsFor(state).find(o=>o.object_id===objectId);}
function creatorMediaView(){const obj=currentObject();if(obj)return objectDetail(obj);const loose=snapshotItems(state).filter(i=>!i.deleted&&i.target_type==='media'&&!i.asset_id&&!asList(state.creator_board?.links).some(l=>l.target_type===i.target_type&&l.target_id===i.target_id));return heading('找到故事里的人与景','按对象整理素材，比较方案，留下你想用的那一版。',`<button data-action="creator-add-object">添加对象</button><button data-view="media-files">导入与整理素材</button>`)+`<nav class="creator-tabs" aria-label="素材分类">${OBJECT_TYPES.map(([id,label])=>`<button data-object-type="${id}" aria-pressed="${id===objectType}">${label}<span>${objectsFor(state).filter(o=>o.type===id).length}</span></button>`).join('')}</nav><div class="toolbar"><label>查看 <select id="object-status">${[['','全部对象'],['pending','有方案待选择'],['selected','已有选用素材'],['empty','尚无素材']].map(([v,l])=>`<option value="${v}" ${v===objectStatus?'selected':''}>${l}</option>`).join('')}</select></label><label>范围 <select id="object-scope">${optionHTML([...new Set(objectsFor(state).map(o=>o.scope).filter(Boolean))].map(id=>({id,label:scopeLabel(id)})),objectScope,'全项目')}</select></label><input id="object-query" type="search" value="${esc(query)}" placeholder="查找人物、场景或描述" aria-label="查找对象"></div>${renderObjectCards(state,objectType,query,objectStatus,objectScope)}${loose.length?`<div class="creator-loose">${loose.length} 份素材还没有关联对象。<button class="text" data-view="media-files">去整理 →</button></div>`:''}`;}
function objectItem(obj,x){const i=x.item,selected=isSelected(state,obj.object_id,x),reference=x.link?.reference_only,key=itemKey(i),purpose=x.link?.purpose;return `<article class="creator-asset"><button class="object-cover" data-open-key="${esc(key)}">${thumbSlot(i)}</button><div class="object-copy"><h3>${esc(i.title)}</h3>${badge(reference?'':selected?'approved':'pending_review',reference?'参考素材':selected?'当前选用':purpose?'候选方案':'用途待整理')}<div class="actions"><button class="text small" data-open-key="${esc(key)}">查看</button>${i.target_type==='media'&&!reference&&purpose&&!selected?`<button class="primary small" data-asset-select="${esc(key)}">选作${esc(purpose)}</button>`:''}<button class="text small" data-asset-link="${esc(key)}">整理用途</button>${i.target_type==='media'?`<button class="text small" data-original="${esc(key)}">取用原件 ↗</button>`:''}</div></div></article>`;}
function objectDetail(obj){const rows=linkedItems(state,obj),purposes=[...new Set(rows.map(x=>x.link?.purpose||'待整理用途'))];return `<button class="text" data-action="creator-back">← 返回对象列表</button>`+heading(obj.title,obj.intro||'查看这个对象的素材与选用结果。',`<button data-object-edit="${esc(obj.object_id)}">编辑对象</button>${chatButton(state,['character','scene','prop'].includes(obj.type)?'art':obj.type==='shot'?'director':'making',null,'进入工作对话 ↗')}`)+`<p class="dim">${rows.length} 份素材 · ${esc(scopeLabel(obj.scope))}</p>${purposes.map(p=>{const members=rows.filter(x=>(x.link?.purpose||'待整理用途')===p),chosen=members.filter(x=>isSelected(state,obj.object_id,x)),others=members.filter(x=>!isSelected(state,obj.object_id,x));return `<section class="creator-purpose"><div class="panel-head"><h2>${esc(p)}</h2>${members.length>1?`<button class="text small" data-asset-compare="${esc(p)}">比较全部方案 →</button>`:''}</div>${chosen.length?`<div class="creator-asset-grid">${chosen.map(x=>objectItem(obj,x)).join('')}</div>${others.length?`<details><summary>其他方案 · ${others.length} 份</summary><div class="creator-asset-grid">${others.map(x=>objectItem(obj,x)).join('')}</div></details>`:''}`:`<div class="creator-asset-grid">${members.map(x=>objectItem(obj,x)).join('')}</div>`}</section>`;}).join('')||empty('尚未准备素材。可以在工作对话中讨论，或导入已有素材后关联到这个对象。')}<button data-view="media-files">关联已有素材</button>`;}
function objectForm(id){const old=objectsFor(state).find(o=>o.object_id===id),oid=old?.object_id||'object-'+crypto.randomUUID();show(old?'编辑对象':'添加人物、场景或其他对象',`<form>${field('名称','title',old?.title||'','required maxlength="100"')}<label>分类<select name="type">${OBJECT_TYPES.map(([id,l])=>`<option value="${id}" ${id===(old?.type||objectType)?'selected':''}>${l}</option>`).join('')}</select></label>${field('简短说明（选填）','intro',old?.intro||'','maxlength="200"')}<label>适用范围<select name="scope">${optionHTML([...new Set(['project',...objectsFor(state).map(o=>o.scope),...asList(state.tasks).map(t=>t.scope),...snapshotItems(state).map(i=>i.scope)].filter(Boolean))].map(id=>({id,label:scopeLabel(id)})),old?.scope||'project','暂不指定')}</select></label>${formButtons('保存对象')}</form>`);bindForm(async form=>{await manage('board.object.set',{object_id:oid,base_revision:old?.revision||0,...Object.fromEntries(form)});objectType=form.get('type');objectId=oid;view='media';render();notice('对象已保存。');});}
function linkForm(item){const objects=objectsFor(state).filter(o=>!o.legacy_association),link=asList(state.creator_board?.links).find(l=>l.target_type===item.target_type&&l.target_id===item.target_id&&(l.version||null)===(item.version||null));if(!objects.length)return show('先添加一个对象',`<p>请先在素材库中添加人物、场景或其他对象，再关联素材。</p><button data-action="creator-add-object">添加对象</button>`);show('整理素材用途 · '+item.title,`<form><label>所属对象<select name="object_id">${objects.map(o=>`<option value="${esc(o.object_id)}" ${o.object_id===(link?.object_id||objectId)?'selected':''}>${esc(o.title)}</option>`).join('')}</select></label>${field('具体用途','purpose',link?.purpose||'','required maxlength="100" placeholder="例如：基础形象、日常造型、雨夜空间"')}<label>素材性质<select name="reference"><option value="false" ${!link?.reference_only?'selected':''}>制作候选</option><option value="true" ${link?.reference_only?'selected':''}>仅作参考</option></select></label>${formButtons('保存用途')}</form>`);bindForm(async form=>{await manage('board.asset.link',{...exactRef(item,state.project.project_id),base_revision:link?.revision||0,object_id:form.get('object_id'),purpose:form.get('purpose'),reference:form.get('reference')==='true'});notice('素材用途已保存。');});}
function selectForm(item){const link=asList(state.creator_board?.links).find(l=>l.target_type===item.target_type&&l.target_id===item.target_id&&(l.version||null)===(item.version||null));if(!link||link.reference_only)throw new Error('请先核对素材的对象和用途；参考素材不能选用。');const obj=objectsFor(state).find(o=>o.object_id===link.object_id),old=selectionFor(state,link.object_id,link.purpose);show('确认选用这份素材？',`<div class="confirm-target"><small>${esc(obj?.title||link.object_id)} / ${esc(link.purpose)}</small><h3>${esc(item.title)}</h3></div><p>只更新这个对象的对应用途。其他用途不变，之前选用的素材仍可回看。</p><form>${field('选用意见（选填）','note','','maxlength="1000"')}${formButtons('确认选用')}</form>`);bindForm(async form=>{await manage('board.asset.select',{...exactRef(item,state.project.project_id),object_id:link.object_id,purpose:link.purpose,base_revision:old?.revision||0,link_revision:link.revision,confirmed:true,note:form.get('note')});notice('已选用，并保留其他候选。');});}
async function confirmForm(item){if(!canConfirm(item))throw new Error('当前内容已采用或不是可确认的最新候选。');const token=capture(),record=await readArtifact(item.target_id,item.version,item.sha256);assertCurrent(token);const basis=asList(state.creator_board?.confirm_targets).find(x=>x.artifact_id===item.target_id&&x.version===item.version&&x.sha256===item.sha256);if(!basis)throw new Error('确认依据已变化，请刷新后重新阅读。');show('确认采用这一版？',`<div class="confirm-target"><h3>${esc(item.title)} · 第 ${item.version} 版</h3><p>${esc(scopeLabel(record.scope))}</p></div><p>这版内容将作为当前采用版本。已有的历史版本会保留，后续创作不会自动开始。</p><form>${field('确认意见（选填）','note','','maxlength="1000"')}${formButtons('确认采用')}</form>`);bindForm(async form=>{await manage('board.confirm',{...exactRef(item,state.project.project_id),base_master_version:basis.base_master_version,base_latest_version:item.latest_working_version||item.version,confirmed:true,note:form.get('note')});notice('已确认这一版，相关记录已更新。');});}
function creatorSettings(){const p=state?.project;if(!p)return projectsList1180(false);const registered=asList(catalog.projects).find(c=>c.project_id===p.project_id),o=state.board_library?.overview||{},scope=asList(o.declared_scope).map(r=>creativeText(r.value)).filter(Boolean).join('；');return heading('项目设置','修改基本资料，查看创作要求，或把暂时不做的项目收起来。',`<button data-view="overview">返回项目总览</button>`)+`<section class="panel"><div class="panel-head"><h2>基本信息</h2><button data-action="creator-profile">修改基本信息</button></div><div class="creator-settings-info">${p.cover?thumbSlot(snapshotItems(state).find(i=>i.target_type==='media'&&i.target_id===p.cover.media_id&&i.sha256===p.cover.sha256),'封面'):'<div class="cover-default">影</div>'}<div><h3>${esc(p.title)}</h3><p>${esc(p.intro||'未填写介绍')}</p><button class="text small" data-action="creator-cover">选择封面</button></div></div></section><section class="panel"><div class="panel-head"><h2>创作要求</h2>${chatButton(state,'plan',null,'讨论调整 ↗')}</div><dl class="creator-requirements"><div><dt>创作路线</dt><dd>${esc({screenplay:'直接剧本',novel_only:'小说创作',novel_to_screen:'小说改编'}[p.workflow?.mode]||'未确定')}</dd></div><div><dt>计划范围</dt><dd>${esc(scope||'未确定')}</dd></div><div><dt>全剧视觉方向</dt><dd>${asList(o.global_baseline).length?asList(o.global_baseline).map(i=>`<button class="text small" data-open-key="${esc(itemKey(i))}">${esc(i.title)}</button>`).join(''):'未确定'}</dd></div></dl></section><section class="panel"><h2>项目管理</h2><div class="record-row"><div><h3>作品文件夹</h3><p class="dim">文稿、素材和项目资料的本地保存位置。</p></div>${registered?`<button data-project-folder="${esc(p.project_id)}">打开作品文件夹 ↗</button>`:`<button data-open-path="${esc(root)}">打开作品文件夹 ↗</button>`}</div><div class="record-row"><div><h3>归档项目</h3><p class="dim">从日常列表收起，随时可以恢复。</p></div>${registered?`<button data-project-visibility="${esc(p.project_id)}" data-status="archived">归档项目</button>`:'<button data-action="register-project">关联到项目列表</button>'}</div><div class="record-row"><div><h3>从看板移除</h3><p class="dim">本地作品文件和已有工作对话保留。</p></div>${registered?`<button class="danger" data-project-forget="${esc(p.project_id)}">从看板移除</button>`:''}</div></section><div class="actions"><button data-view="project-list">管理项目列表</button><button data-view="archives">已归档项目</button><button data-view="trash">素材回收站</button><button data-view="exports">已导出资料</button></div>`;}
function profileForm(){const p=state.project;show('项目基本信息',`<form>${field('项目名称','title',p.title,'required maxlength="40"')}<label>一句话介绍（选填）<textarea name="intro" maxlength="200">${esc(p.intro||'')}</textarea></label>${formButtons('保存修改')}</form>`);bindForm(async form=>{await manage('board.project.set',{base_revision:p.profile_revision||0,title:form.get('title'),intro:form.get('intro')||'',cover:p.cover||null});notice('项目资料已保存。');});}
function coverForm(){const p=state.project,items=snapshotItems(state).filter(i=>i.target_type==='media'&&i.kind==='image'&&!i.deleted);show('选择项目封面',`<form><label>封面素材<select name="cover"><option value="">默认封面</option>${items.map(i=>`<option value="${esc(itemKey(i))}" ${p.cover?.media_id===i.target_id?'selected':''}>${esc(i.title)}</option>`).join('')}</select></label><p class="quiet-note">封面只用于项目展示，不改变素材选用状态。</p>${formButtons('保存封面')}</form>`);bindForm(async form=>{const item=items.find(i=>itemKey(i)===form.get('cover'));await manage('board.project.set',{base_revision:p.profile_revision||0,title:p.title,intro:p.intro||'',cover:item?{media_id:item.target_id,sha256:item.sha256}:null});notice('封面已保存。');});}
function projectsList1180(archived){const rows=asList(catalog.projects).filter(p=>(p.status==='archived')===archived);return heading(archived?'已归档项目':'项目列表',archived?'恢复后继续使用原来的内容和进度。':'切换项目或关联已有作品文件夹。',`<button data-view="${archived?'project-list':'archives'}">${archived?'返回日常项目':'已归档项目'}</button>${archived?'':'<button data-action="register-project">关联已有项目</button>'}`)+`<section class="panel">${rows.length?rows.map(p=>`<div class="record-row"><div><h3>${esc(p.title)}</h3><p class="dim">${esc(p.intro||'')}${p.available===false?' · 文件夹位置待核对':''}</p></div><div class="actions">${archived?`<button data-project-visibility="${esc(p.project_id)}" data-status="active">恢复到项目列表</button>`:`<button data-project-open="${esc(p.project_id)}" ${p.available===false?'disabled':''}>打开</button><button data-project-visibility="${esc(p.project_id)}" data-status="archived">归档</button>`}<button class="text small" data-project-relink="${esc(p.project_id)}">更新文件夹位置</button><button class="text small" data-project-forget="${esc(p.project_id)}">从看板移除</button></div></div>`).join(''):empty(archived?'没有已归档项目。':'日常项目列表暂时为空，可以恢复归档项目或关联已有作品。')}</section>`;}
function visibilityForm(id,status){const p=asList(catalog.projects).find(p=>p.project_id===id);if(!p)throw new Error('项目登记已变化，请刷新。');show(status==='archived'?'归档这个项目？':'恢复这个项目？',`<div class="confirm-target"><h3>${esc(p.title)}</h3></div><p>${status==='archived'?'项目将从日常列表收起，文件、任务、素材、确认记录和工作对话保留。':'项目将回到日常列表，原有内容和进度保持不变。'}</p><form>${formButtons(status==='archived'?'确认归档':'恢复到项目列表')}</form>`);bindForm(async()=>{await manage('projects.visibility',{project_id:id,expected_root:p.root,base_revision:p.revision||0,status});notice(status==='archived'?'项目已归档，可在已归档项目中恢复。':'项目已恢复，可以从项目选择器打开。');});}
function creatorReviews(){const decisions=asList(state.creator_board?.decisions);return heading('确认记录','回看已做过的决定，以及当前采用的内容。',`<button data-view="overview">返回项目总览</button>`)+decisions.map(d=>{const obj=objectsFor(state).find(o=>o.object_id===d.object_id),current=selectionFor(state,d.object_id,d.purpose)?.decision_id===d.decision_id,item=snapshotItems(state).find(i=>i.target_type===d.reference.target_type&&i.target_id===d.reference.target_id&&i.sha256===d.reference.sha256);return `<article class="review-card">${badge(current?'approved':'',current?'当前选用':'已被后续选择替代')}<h3>${esc(obj?.title||d.object_id)} · ${esc(d.purpose)}</h3><p>${esc(item?.title||'所选素材')}</p><small>${esc(stamp(d.observed_at))}</small>${d.note?`<p>${esc(d.note)}</p>`:''}${item?`<button class="small" data-open-key="${esc(itemKey(item))}">查看当时选择</button>`:''}</article>`;}).join('')+styleDecisionRecords()+renderReviewCards(state,{query,filter:'adoption'});}
async function fillCreatorThumbnails(){const round=++thumbnailRound,token=capture(),nodes=Array.from(el('content').querySelectorAll?.('[data-thumbnail]')||[]).slice(0,24);for(let start=0;start<nodes.length;start+=3){await Promise.all(nodes.slice(start,start+3).map(async node=>{const item=itemByKey(node.dataset.thumbnail);if(!item)return;const key=token.project_id+'|'+itemKey(item);try{let uri=thumbnailCache.get(key);if(!uri){const action=item.kind==='image'?'media.preview_image':'media.preview',result=await call(action,{expected_project_id:token.project_id,media_id:item.target_id});verifyPreview(result,item,token.project_id);uri=safePreviewURI(result.thumbnail_data_uri,'image')||(item.kind==='image'?safePreviewURI(result.preview_data_uri,'image'):null);if(uri)thumbnailCache.set(key,uri);}if(round!==thumbnailRound||!isCurrent(token))return;node.innerHTML=uri?`<img src="${esc(uri)}" alt="${esc(item.title)}">`:'<span>预览暂不可用 · 点击查看原件</span>';}catch{if(round===thumbnailRound&&isCurrent(token))node.innerHTML='<span>预览暂不可用 · 点击查看</span>';}}));}}
async function creatorAction(d){if(d.styleCompare){await styleCompareForm(d.styleCompare);return true;}if(d.styleChoice){styleChoiceForm(d.comparison,d.styleChoice);return true;}if(d.stage){creatorStage=d.stage;view='tasks';render();return true;}if(d.objectType){objectType=d.objectType;objectId=null;query='';view='media';render();return true;}if(d.object){objectId=d.object;view='media';render();return true;}if(d.objectEdit){objectForm(d.objectEdit);return true;}if(d.assetLink){const item=itemByKey(d.assetLink);if(!item)throw new Error('素材已变化，请刷新。');linkForm(item);return true;}if(d.assetSelect){const item=itemByKey(d.assetSelect);if(!item)throw new Error('素材已变化，请刷新。');selectForm(item);return true;}if(d.confirmArtifact){const item=itemByKey(d.confirmArtifact);if(!item)throw new Error('文稿已变化，请刷新。');await confirmForm(item);return true;}if(d.projectVisibility){visibilityForm(d.projectVisibility,d.status);return true;}if(d.assetCompare){const obj=currentObject();if(obj){show(obj.title+' · '+d.assetCompare,`<div class="creator-asset-grid">${linkedItems(state,obj).filter(x=>(x.link?.purpose||'待整理用途')===d.assetCompare).map(x=>objectItem(obj,x)).join('')}</div>`);void fillDialogThumbnails();}return true;}switch(d.action){case 'creator-add-object':objectForm();return true;case 'creator-back':objectId=null;render();return true;case 'creator-profile':profileForm();return true;case 'creator-cover':coverForm();return true;default:return false;}}
async function fillDialogThumbnails(){const token=capture(),session=dialogSession,nodes=Array.from(el('dialog-body').querySelectorAll?.('[data-thumbnail]')||[]);for(const node of nodes.slice(0,12)){const item=itemByKey(node.dataset.thumbnail);if(!item)continue;try{const data=await call(item.kind==='image'?'media.preview_image':'media.preview',{expected_project_id:token.project_id,media_id:item.target_id});verifyPreview(data,item,token.project_id);const uri=safePreviewURI(data.thumbnail_data_uri,'image')||(item.kind==='image'?safePreviewURI(data.preview_data_uri,'image'):null);if(session!==dialogSession||!isCurrent(token))return;node.innerHTML=uri?`<img src="${esc(uri)}" alt="${esc(item.title)}">`:'<span>请单独查看原件</span>';}catch{if(session===dialogSession&&isCurrent(token))node.innerHTML='<span>预览暂不可用</span>';}}}

async function styleCompareForm(id){const token=capture(),data=await call('art.read',{expected_project_id:token.project_id,comparison_id:id,include_content:true});assertCurrent(token);if(data.revision!==state.art?.revision)throw new Error('方案已更新，请刷新后重新比较。');show(data.comparison.title,`<p>阅读同一创作要求下的两套完整方案，再选择要继续完善的方向。</p><div class="creator-asset-grid">${['main','alternate'].map(choice=>{const a=data.proposals[choice];return `<section class="panel"><h2>${choice==='main'?'主选方案':'备选方案'}</h2><article class="prose">${renderProse(a.content)}</article><button class="primary" data-style-choice="${choice}" data-comparison="${esc(id)}">选用这套方案</button></section>`;}).join('')}</div>`);}
function styleChoiceForm(id,choice){const art=state.art,c=asList(art?.comparisons).find(c=>c.comparison_id===id),ref=c?.[choice];if(!ref)throw new Error('方案已变化，请刷新后重新比较。');show('确认选用'+(choice==='main'?'主选方案':'备选方案')+'？',`<p>保存你的方向选择。美术工作对话可据此继续整理完整视觉基准，现有已采用内容仍保留。</p><form>${field('选择意见（选填）','note','','maxlength="1000"')}${formButtons('确认选用方案')}</form>`);bindForm(async form=>{await manage('board.style.select',{comparison_id:id,choice,target_id:ref.artifact_id,version:ref.version,expected_sha256:ref.sha256,base_revision:art.revision,confirmed:true,note:form.get('note')});notice('方案选择已保存，可进入美术工作对话继续。');});}

function styleDecisionRecords(){const art=state.art||{};return asList(art.selections).slice().reverse().map(d=>`<article class="review-card">${badge('',d.selection_id===art.active_selection_id?'当前选用方向':'历史方向选择')}<h3>${esc(asList(art.comparisons).find(c=>c.comparison_id===d.comparison_id)?.title||'视觉方向')} · ${esc({main:'主选方案',alternate:'备选方案',fusion:'融合方案'}[d.choice]||'方案')}</h3><p>${esc(d.user_request?.quote||'')}</p><small>${esc(stamp(d.selected_at))}</small><p class="dim">方向选择已保存，完整视觉基准的采用另行确认。</p><button class="small" data-read-artifact="${esc(d.selected.artifact_id)}" data-version="${esc(d.selected.version)}">查看当时方案</button></article>`).join('');}
